framework/briefing/commitments.py:
"""Ticket 10: typed commitment registry loading (fail closed).

The real file lives outside the repo; only synthetic fixtures and
``tmp_path`` files are read in tests.
"""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any, cast

from pydantic import ValidationError

from framework.briefing.gate import action_targets_repo, text_check_codes
from framework.briefing.schemas import Commitment

_UNSET = "unset"
_UNREADABLE = "unreadable"
_NOT_UTF8 = "not_utf8"
_INVALID_JSON = "invalid_json"
_NOT_A_LIST = "not_a_list"
_EMPTY = "empty"
_INVALID_ITEM = "invalid_item"
_DUPLICATE_ID = "duplicate_id"
_TITLE_FAILED = "title_failed"


@dataclass(frozen=True)
class LoadedCommitments:
    """Loaded commitments plus their availability (fail closed)."""

    commitments: tuple[Commitment, ...]
    available: bool
    reason: str | None


def _failed(reason: str) -> LoadedCommitments:
    return LoadedCommitments((), False, reason)


def load_commitments(
    environ: Mapping[str, str] | None = None,
    *,
    private_terms: tuple[str, ...] = (),
    forbidden_raw_literals: tuple[str, ...] = (),
) -> LoadedCommitments:
    """Load the JSON commitment list named by ``IKIGAI_COMMITMENTS_FILE``.

    Reads the variable at call time only. Any failure returns no
    commitments with ``available`` False and one closed reason value, with
    no exception and no path or file content in any message, output or
    log. The whole file is rejected when any title fails the title
    checks.
    """
    env: Mapping[str, str] = os.environ if environ is None else environ
    raw_path = env.get("IKIGAI_COMMITMENTS_FILE", "")
    if not raw_path:
        return _failed(_UNSET)
    try:
        data = Path(raw_path).read_bytes()
    except (OSError, ValueError):
        return _failed(_UNREADABLE)
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return _failed(_NOT_UTF8)
    try:
        parsed: Any = json.loads(text)
    except (ValueError, RecursionError):
        return _failed(_INVALID_JSON)
    if not isinstance(parsed, list):
        return _failed(_NOT_A_LIST)
    items = cast("list[Any]", parsed)
    if not items:
        return _failed(_EMPTY)
    commitments: list[Commitment] = []
    try:
        for item in items:
            commitments.append(Commitment.model_validate(item))
    except (ValidationError, TypeError):
        return _failed(_INVALID_ITEM)
    seen: set[str] = set()
    for commitment in commitments:
        if commitment.id in seen:
            return _failed(_DUPLICATE_ID)
        seen.add(commitment.id)
    for commitment in commitments:
        if text_check_codes(
            commitment.title,
            private_terms=private_terms,
            forbidden_raw_literals=forbidden_raw_literals,
        ):
            return _failed(_TITLE_FAILED)
        if action_targets_repo(commitment.title):
            return _failed(_TITLE_FAILED)
    return LoadedCommitments(tuple(commitments), True, None)

framework/briefing/context.py:
"""Ticket 8: gate reference data (``GateContext``) and private-terms loading.

Building a context is the only place env/files are read;
``evaluate_briefing`` itself is pure.
"""

from __future__ import annotations

import os
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import time
from pathlib import Path
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from pydantic import AwareDatetime, Field, field_validator, model_validator

from framework.briefing.schemas import Briefing, Commitment
from framework.schemas.base import SchemaModel
from framework.schemas.core import Fact
from framework.schemas.events import NonEmptyStr


class TimeInterval(SchemaModel):
    """Half-open ``[start, end)`` interval."""

    start: AwareDatetime
    end: AwareDatetime

    @model_validator(mode="after")
    def _end_after_start(self) -> TimeInterval:
        if self.end <= self.start:
            raise ValueError("interval end must be after start")
        return self


class MetricSnapshot(SchemaModel):
    """Point-in-time metric values; empty is valid (claims-free briefings)."""

    values: dict[NonEmptyStr, float] = Field(default_factory=dict)

    @field_validator("values")
    @classmethod
    def _finite_values(cls, values: dict[str, float]) -> dict[str, float]:
        import math

        for metric_id, value in values.items():
            if not math.isfinite(value):
                raise ValueError(f"metric value must be finite: {metric_id}")
        return values


class ProfileLimits(SchemaModel):
    """Typed limits a caller encodes; the gate never parses markdown."""

    timezone: NonEmptyStr
    allowed_start: time
    allowed_end: time
    max_actions: int = Field(default=3, ge=1, le=3)

    @field_validator("timezone")
    @classmethod
    def _known_timezone(cls, timezone: str) -> str:
        try:
            ZoneInfo(timezone)
        except ZoneInfoNotFoundError as exc:
            raise ValueError(f"unknown timezone: {timezone}") from exc
        return timezone

    @model_validator(mode="after")
    def _same_day_window(self) -> ProfileLimits:
        if self.allowed_start >= self.allowed_end:
            raise ValueError("allowed_start must be before allowed_end")
        return self


class GateContext(SchemaModel):
    """Reference data the gate reconciles one briefing against."""

    facts: dict[NonEmptyStr, Fact] = Field(default_factory=dict)
    metrics: MetricSnapshot = Field(default_factory=MetricSnapshot)
    parent_briefing: Briefing | None = None
    parent_metrics: MetricSnapshot | None = None
    free_intervals: tuple[TimeInterval, ...] = ()
    busy_intervals: tuple[TimeInterval, ...] = ()
    limits: ProfileLimits
    check_slot: bool = True
    private_terms: tuple[str, ...] = ()
    private_terms_available: bool = False
    raw_metric_ids: frozenset[NonEmptyStr] = frozenset()
    forbidden_raw_literals: tuple[NonEmptyStr, ...] = ()
    commitments: tuple[Commitment, ...] = ()
    commitments_available: bool = False

    @field_validator("facts")
    @classmethod
    def _keys_match_ids(cls, facts: dict[str, Fact]) -> dict[str, Fact]:
        for key, fact in facts.items():
            if key != fact.id:
                raise ValueError("facts key must equal its Fact.id")
        return facts

    @model_validator(mode="after")
    def _parent_pair(self) -> GateContext:
        if (self.parent_briefing is None) != (self.parent_metrics is None):
            raise ValueError(
                "parent_briefing and parent_metrics must both be present or both absent"
            )
        return self

    @model_validator(mode="after")
    def _unique_commitment_ids(self) -> GateContext:
        seen: set[str] = set()
        for commitment in self.commitments:
            if commitment.id in seen:
                raise ValueError("commitment ids must be unique")
            seen.add(commitment.id)
        return self


@dataclass(frozen=True)
class PrivateTerms:
    """Loaded private terms plus their availability (fail closed)."""

    terms: tuple[str, ...]
    available: bool


def load_private_terms(
    environ: Mapping[str, str] | None = None,
    *,
    allow_missing_for_tests: bool = False,
) -> PrivateTerms:
    """Load private terms from ``deny-terms.txt`` in ``HIDDEN_CRITERIA_DIR``.

    The directory may hold other criteria files, so only ``deny-terms.txt``
    is read. The file holds one term per line; blank lines and lines
    starting with ``#`` are ignored. Matching is case-insensitive; terms of
    3 characters or fewer match whole words only, longer terms match as
    substrings (see the gate). Reads the variable at call time only.
    Unset/empty passes terms only when the caller passes
    ``allow_missing_for_tests=True``; every production caller uses the
    default. A missing file, a file with no terms, a non-UTF-8 file, or any
    line starting with ``- `` or ``* `` fails closed with no exception and
    no path in any message. Terms are never logged. The one-term-per-line
    ``deny-terms.txt`` layout is an assumption (see the session note).
    """
    env: Mapping[str, str] = os.environ if environ is None else environ
    raw_dir = env.get("HIDDEN_CRITERIA_DIR", "")
    if not raw_dir:
        return PrivateTerms((), available=allow_missing_for_tests)
    try:
        data = (Path(raw_dir) / "deny-terms.txt").read_bytes()
    except OSError:
        return PrivateTerms((), available=False)
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return PrivateTerms((), available=False)
    terms: list[str] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith(("- ", "* ")):
            return PrivateTerms((), available=False)
        if stripped not in terms:
            terms.append(stripped)
    if not terms:
        return PrivateTerms((), available=False)
    return PrivateTerms(tuple(terms), available=True)

framework/briefing/gate.py:
"""Ticket 8: deterministic briefing gate (L0 structure, L1 rules, L1b).

No network, no model call, no env read, no clock read: all times come from
the briefing/context. Messages never interpolate a matched secret, email,
private term, or raw value. Identical ``(code, location)`` pairs are
de-duplicated once at the end; the result is sorted by
``(layer, code, location)`` so section input order cannot change it.
"""

from __future__ import annotations

import itertools
import re
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import datetime
from decimal import ROUND_HALF_UP, Decimal
from typing import Any, Literal, cast
from zoneinfo import ZoneInfo

from pydantic import ValidationError

from framework.briefing.context import GateContext, TimeInterval
from framework.briefing.labels import MetricBinding, metric_label_binding
from framework.briefing.numbers import extract_number_tokens
from framework.briefing.schemas import Action, Briefing, Claim

Layer = Literal["L0", "L1", "L1b"]

REQUIRED_SECTIONS = ("overall_state", "working", "not_working", "actions")
KNOWN_SECTION_TYPES = frozenset(
    ["overall_state", "since_last", "working", "not_working", "actions"]
)

_SECRET_PATTERNS = tuple(
    re.compile(pattern, re.IGNORECASE)
    for pattern in (
        r"\bghp_[A-Za-z0-9_-]{16,}",
        r"\bgho_[A-Za-z0-9_-]{16,}",
        r"\bgithub_pat_[A-Za-z0-9_-]{16,}",
        r"\bglpat-[A-Za-z0-9_-]{16,}",
        r"\bsk-[A-Za-z0-9_-]{16,}",
        r"\bAKIA[A-Za-z0-9_-]{16,}",
        r"\bxox[baprs]-[A-Za-z0-9_-]{16,}",
        r"\bBearer\s+\S{16,}",
        r"-----BEGIN [A-Za-z0-9 ]*PRIVATE KEY-----",
        r"(?:api[_-]?key|secret|token|password)\s*[:=]\s*\S+",
        r"\b[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.ts\.net\b",
    )
)
_EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
_PHONE_RE = re.compile(r"\+\d[\d ()-]{7,}\d")
_REPO_TERMS = ("ikigai-loop", "ikigai_loop", "ikigai loop")
_ADVICE_SINGLES = frozenset(
    [
        "should",
        "must",
        "diet",
        "diets",
        "calorie",
        "calories",
        "medication",
        "medications",
        "medicine",
        "medicines",
        "dose",
        "doses",
        "dosage",
        "dosages",
        "symptom",
        "symptoms",
        "diagnosis",
        "diagnoses",
        "treatment",
        "treatments",
        "therapy",
        "therapies",
        "intensity",
        "shouldn't",
        "mustn't",
    ]
)
_ADVICE_PHRASES = ("push harder", "rest more")
_PERIOD_WORDS = ("earlier", "prior", "last")
_UP_WORDS = frozenset(
    [
        "up",
        "rose",
        "rise",
        "rises",
        "rising",
        "risen",
        "increase",
        "increased",
        "increases",
        "increasing",
        "more",
        "higher",
        "grew",
        "grow",
        "grows",
        "growing",
        "grown",
    ]
)
_DOWN_WORDS = frozenset(
    [
        "down",
        "fell",
        "fall",
        "falls",
        "falling",
        "fallen",
        "decrease",
        "decreased",
        "decreases",
        "decreasing",
        "less",
        "fewer",
        "lower",
        "dropped",
        "drop",
        "drops",
        "dropping",
    ]
)
_PERIOD_ORDER = {"earlier": 0, "prior": 1, "last": 2}
_DIRECTION_TOKEN_RE = re.compile(r"\w+(?:-\w+)*")
_PERIOD_MESSAGE = "period words do not match the cited metrics"


def text_check_codes(
    text: str,
    *,
    private_terms: tuple[str, ...] = (),
    forbidden_raw_literals: tuple[str, ...] = (),
) -> tuple[str, ...]:
    """L1 text verdicts for one text; never ``L1_ACTION_TARGETS_REPO``."""
    codes: list[str] = []
    if any(pattern.search(text) for pattern in _SECRET_PATTERNS):
        codes.append("L1_SECRET")
    if _EMAIL_RE.search(text) or _PHONE_RE.search(text):
        codes.append("L1_PII")
    normalized = _collapse(text).replace("\u2019", "'").replace("\u2018", "'")
    if any(_contains_token(normalized, word) for word in _ADVICE_SINGLES) or any(
        _contains_token(normalized, phrase) for phrase in _ADVICE_PHRASES
    ):
        codes.append("L1_ADVICE")
    collapsed_terms = [_collapse(term) for term in private_terms]
    collapsed = _collapse(text)
    for term in collapsed_terms:
        if not term:
            continue
        if len(term) <= 3:
            hit = _contains_token(collapsed, term)
        else:
            hit = term in collapsed
        if hit:
            codes.append("L1_PRIVATE_TERM")
            break
    if any(
        _contains_token(collapsed, _collapse(literal))
        for literal in forbidden_raw_literals
        if _collapse(literal)
    ):
        codes.append("L1_RAW_VALUE")
    return tuple(codes)


def action_targets_repo(text: str) -> bool:
    """Whether action text names this repo."""
    lowered = text.casefold()
    return any(term in lowered for term in _REPO_TERMS)


_ACTION_WINDOW_MESSAGES = {
    "L1_ACTION_BEFORE_SLOT": "action starts before the briefing slot",
    "L1_ACTION_IN_BUSY_INTERVAL": "action overlaps a busy interval",
    "L1_ACTION_NOT_FREE": "action is not fully inside free time",
}


def action_window_codes(
    start: datetime,
    end: datetime,
    *,
    slot: datetime,
    busy_intervals: tuple[TimeInterval, ...],
    free_intervals: tuple[TimeInterval, ...],
) -> tuple[str, ...]:
    """Window verdicts for one proposed range; no env, clock or network."""
    codes: list[str] = []
    if start < slot:
        codes.append("L1_ACTION_BEFORE_SLOT")
    if any(start < busy.end and busy.start < end for busy in busy_intervals):
        codes.append("L1_ACTION_IN_BUSY_INTERVAL")
    elif not any(
        free_start <= start and end <= free_end
        for free_start, free_end in _merge_intervals(free_intervals)
    ):
        codes.append("L1_ACTION_NOT_FREE")
    return tuple(codes)


@dataclass(frozen=True)
class Violation:
    """One stable gate finding; ``message`` never echoes matched content."""

    code: str
    layer: Layer
    location: str
    message: str


@dataclass(frozen=True)
class GateResult:
    """Sorted, de-duplicated violations for one briefing."""

    violations: tuple[Violation, ...]

    @property
    def passed(self) -> bool:
        """A briefing passes iff it has no violations."""
        return self.violations == ()


def _section_location(section_type: str) -> str:
    return f"sections[{section_type}]"


def _claim_location(section_type: str, claim_id: str) -> str:
    return f"sections[{section_type}].claims[{claim_id}]"


def _action_location(action_id: str) -> str:
    return f"sections[actions].actions[{action_id}]"


def _iter_texts(
    briefing: Briefing,
) -> tuple[tuple[str, str, str, str], ...]:
    """(kind, owner_id, text, location) for every scanned claim/action text."""
    rows: list[tuple[str, str, str, str]] = []
    for section in briefing.sections:
        for claim in section.claims:
            rows.append(
                (
                    "claim",
                    claim.id,
                    claim.text,
                    _claim_location(section.type, claim.id),
                )
            )
        for action in section.actions:
            rows.append(("action", action.id, action.text, _action_location(action.id)))
    return tuple(rows)


def _iter_claims(
    briefing: Briefing,
) -> tuple[tuple[str, Claim], ...]:
    return tuple(
        (section.type, claim)
        for section in briefing.sections
        for claim in section.claims
    )


def _iter_actions(briefing: Briefing) -> tuple[Action, ...]:
    return tuple(action for section in briefing.sections for action in section.actions)


def _collapse(text: str) -> str:
    return " ".join(text.split()).casefold()


def _contains_token(text: str, literal: str) -> bool:
    start = 0
    while True:
        index = text.find(literal, start)
        if index < 0:
            return False
        before = text[index - 1] if index > 0 else ""
        end = index + len(literal)
        after = text[end] if end < len(text) else ""
        if not (before.isalnum() or before == "_") and not (
            after.isalnum() or after == "_"
        ):
            return True
        start = index + 1


def _merge_intervals(
    intervals: tuple[TimeInterval, ...],
) -> tuple[tuple[datetime, datetime], ...]:
    spans = sorted(
        ((item.start, item.end) for item in intervals), key=lambda span: span[0]
    )
    merged: list[list[datetime]] = []
    for start, end in spans:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return tuple((start, end) for start, end in merged)


def _l0_counts(briefing: Briefing, context: GateContext) -> list[Violation]:
    violations: list[Violation] = []
    types = [section.type for section in briefing.sections]
    for section_type, count in Counter(types).items():
        if count > 1:
            violations.append(
                Violation(
                    "L0_DUPLICATE_SECTION",
                    "L0",
                    _section_location(section_type),
                    "section type appears more than once",
                )
            )
    for section_type in REQUIRED_SECTIONS:
        if section_type not in types:
            violations.append(
                Violation(
                    "L0_MISSING_SECTION",
                    "L0",
                    _section_location(section_type),
                    "required section is missing",
                )
            )
    if len(types) > 5:
        violations.append(
            Violation("L0_SECTION_COUNT", "L0", "sections", "too many sections")
        )
    for section in briefing.sections:
        if section.type == "overall_state" and not section.claims:
            violations.append(
                Violation(
                    "L0_EMPTY_SECTION",
                    "L0",
                    _section_location(section.type),
                    "section must carry at least one claim",
                )
            )
        if section.type == "since_last" and not section.claims:
            violations.append(
                Violation(
                    "L0_EMPTY_SECTION",
                    "L0",
                    _section_location(section.type),
                    "section must carry at least one claim",
                )
            )
    limit = min(3, context.limits.max_actions)
    for section in briefing.sections:
        if section.type == "actions":
            if len(section.actions) < 1 or len(section.actions) > limit:
                violations.append(
                    Violation(
                        "L0_ACTION_COUNT",
                        "L0",
                        _section_location(section.type),
                        "action count outside 1..limit",
                    )
                )
        elif section.actions:
            violations.append(
                Violation(
                    "L0_ACTION_COUNT",
                    "L0",
                    _section_location(section.type),
                    "action count outside 1..limit",
                )
            )
    seen: dict[str, str] = {}
    for section in briefing.sections:
        for claim in section.claims:
            location = _claim_location(section.type, claim.id)
            if claim.id in seen:
                violations.append(
                    Violation(
                        "L0_DUPLICATE_ID",
                        "L0",
                        location,
                        "id is used more than once",
                    )
                )
            else:
                seen[claim.id] = location
        for action in section.actions:
            location = _action_location(action.id)
            if action.id in seen:
                violations.append(
                    Violation(
                        "L0_DUPLICATE_ID",
                        "L0",
                        location,
                        "id is used more than once",
                    )
                )
            else:
                seen[action.id] = location
    return violations


_TEXT_MESSAGES = {
    "L1_SECRET": "secret-like token",
    "L1_PII": "contact detail",
    "L1_ADVICE": "advice-like wording",
    "L1_PRIVATE_TERM": "private term",
    "L1_RAW_VALUE": "raw source value",
}


def _l1_text_checks(briefing: Briefing, context: GateContext) -> list[Violation]:
    violations: list[Violation] = []
    if not context.private_terms_available:
        violations.append(
            Violation(
                "L1_PRIVATE_TERMS_UNAVAILABLE",
                "L1",
                "briefing",
                "private terms unavailable",
            )
        )
        check_terms = False
    else:
        check_terms = True
    for _kind, _owner, text, location in _iter_texts(briefing):
        for code in text_check_codes(
            text,
            private_terms=context.private_terms if check_terms else (),
            forbidden_raw_literals=context.forbidden_raw_literals,
        ):
            violations.append(Violation(code, "L1", location, _TEXT_MESSAGES[code]))
    return violations


def _l1_commitment_checks(briefing: Briefing, context: GateContext) -> list[Violation]:
    violations: list[Violation] = []
    if not context.commitments_available:
        violations.append(
            Violation(
                "L1_COMMITMENTS_UNAVAILABLE",
                "L1",
                "briefing",
                "commitments unavailable",
            )
        )
        return violations
    by_id = {commitment.id: commitment for commitment in context.commitments}
    for action in _iter_actions(briefing):
        location = _action_location(action.id)
        commitment = by_id.get(action.commitment_id)
        if commitment is None or commitment.profile_id != briefing.profile_id:
            violations.append(
                Violation(
                    "L1_ACTION_NOT_COMMITTED",
                    "L1",
                    location,
                    "action is not a user commitment",
                )
            )
            continue
        if (
            _collapse(action.text) != _collapse(commitment.title)
            or action.kind != commitment.kind
            or action.dimension != commitment.dimension
        ):
            violations.append(
                Violation(
                    "L1_ACTION_TEXT_MISMATCH",
                    "L1",
                    location,
                    "action differs from its commitment",
                )
            )
    return violations


def _l1_metric_ref_raw_check(
    briefing: Briefing, context: GateContext
) -> list[Violation]:
    violations: list[Violation] = []
    for section_type, claim in _iter_claims(briefing):
        location = _claim_location(section_type, claim.id)
        if any(
            ref.metric_id in context.raw_metric_ids or ref.metric_id.startswith("raw.")
            for ref in claim.metric_refs
        ):
            violations.append(
                Violation("L1_RAW_VALUE", "L1", location, "raw source value")
            )
    return violations


def _l1_slot_and_interval_checks(
    briefing: Briefing, context: GateContext
) -> list[Violation]:
    violations: list[Violation] = []
    if context.check_slot:
        local = briefing.slot.astimezone(ZoneInfo(context.limits.timezone)).time()
        if not (context.limits.allowed_start <= local < context.limits.allowed_end):
            violations.append(
                Violation(
                    "L1_SLOT_OUTSIDE_ALLOWED_HOURS",
                    "L1",
                    "slot",
                    "slot outside allowed hours",
                )
            )
    for action in _iter_actions(briefing):
        location = _action_location(action.id)
        for code in action_window_codes(
            action.proposed_start,
            action.proposed_end,
            slot=briefing.slot,
            busy_intervals=context.busy_intervals,
            free_intervals=context.free_intervals,
        ):
            violations.append(
                Violation(code, "L1", location, _ACTION_WINDOW_MESSAGES[code])
            )
        if action_targets_repo(action.text):
            violations.append(
                Violation(
                    "L1_ACTION_TARGETS_REPO",
                    "L1",
                    location,
                    "action targets this repo",
                )
            )
    return violations


def _ref_backs_token(value: float, places: int, token_abs: Decimal) -> bool:
    quantum = Decimal(1).scaleb(-places)
    rounded = Decimal(str(value)).quantize(quantum, rounding=ROUND_HALF_UP)
    return abs(rounded) == token_abs


def _is_raw_ref(metric_id: str, context: GateContext) -> bool:
    return metric_id in context.raw_metric_ids or metric_id.startswith("raw.")


def _label_in_text(binding: MetricBinding, collapsed: str) -> bool:
    return any(_contains_token(collapsed, _collapse(label)) for label in binding.labels)


def _binding_violations(
    section_type: str, claim: Claim, context: GateContext, location: str
) -> list[Violation]:
    violations: list[Violation] = []
    remaining = [
        ref for ref in claim.metric_refs if not _is_raw_ref(ref.metric_id, context)
    ]
    if not remaining:
        return violations
    bindings: list[MetricBinding | None] = [
        metric_label_binding(ref.metric_id) for ref in remaining
    ]
    if any(binding is None for binding in bindings):
        violations.append(
            Violation(
                "L1B_METRIC_LABEL_UNKNOWN",
                "L1b",
                location,
                "metric family is unknown",
            )
        )
        return violations
    known = [binding for binding in bindings if binding is not None]
    collapsed = _collapse(claim.text)
    if len(remaining) == 1:
        binding = known[0]
        if not _label_in_text(binding, collapsed):
            violations.append(
                Violation(
                    "L1B_METRIC_LABEL_MISSING",
                    "L1b",
                    location,
                    "claim does not name the cited metric",
                )
            )
        if binding.period is not None and not _contains_token(
            collapsed, binding.period
        ):
            violations.append(
                Violation(
                    "L1B_PERIOD_WORD_MISSING",
                    "L1b",
                    location,
                    _PERIOD_MESSAGE,
                )
            )
        if binding.requires_cancel and "cancel" not in collapsed:
            violations.append(
                Violation(
                    "L1B_METRIC_LABEL_MISSING",
                    "L1b",
                    location,
                    "claim does not name the cited metric",
                )
            )
    else:
        periods = [binding.period for binding in known]
        families = {binding.family for binding in known}
        eligible = (
            2 <= len(remaining) <= 3
            and all(period is not None for period in periods)
            and len(families) == 1
            and len(set(periods)) == len(periods)
        )
        if not eligible:
            violations.append(
                Violation(
                    "L1B_TOO_MANY_METRICS",
                    "L1b",
                    location,
                    "claim cites metrics outside one comparison",
                )
            )
            return violations
        if not _label_in_text(known[0], collapsed):
            violations.append(
                Violation(
                    "L1B_METRIC_LABEL_MISSING",
                    "L1b",
                    location,
                    "claim does not name the cited metric",
                )
            )
        for period in periods:
            assert period is not None
            if not _contains_token(collapsed, period):
                violations.append(
                    Violation(
                        "L1B_PERIOD_WORD_MISSING",
                        "L1b",
                        location,
                        _PERIOD_MESSAGE,
                    )
                )
                break
    if section_type != "since_last":
        cited = {binding.period for binding in known if binding.period is not None}
        named = {word for word in _PERIOD_WORDS if _contains_token(collapsed, word)}
        if named != cited:
            violations.append(
                Violation(
                    "L1B_PERIOD_WORD_MISSING",
                    "L1b",
                    location,
                    _PERIOD_MESSAGE,
                )
            )
    label_tokens: set[str] = set()
    for binding in known:
        for label in binding.labels:
            label_tokens.update(_DIRECTION_TOKEN_RE.findall(_collapse(label)))
    tokens = set(_DIRECTION_TOKEN_RE.findall(collapsed)) - label_tokens
    up_hit = bool(tokens & _UP_WORDS)
    down_hit = bool(tokens & _DOWN_WORDS)
    if up_hit and down_hit:
        violations.append(
            Violation(
                "L1B_DIRECTION_MISMATCH",
                "L1b",
                location,
                "direction words disagree with the cited values",
            )
        )
    elif up_hit or down_hit:
        side = "up" if up_hit else "down"
        if section_type == "since_last":
            signs = {
                (Decimal(str(ref.value)) > 0, Decimal(str(ref.value)) < 0)
                for ref in remaining
            }
            if signs != ({(True, False)} if side == "up" else {(False, True)}):
                violations.append(
                    Violation(
                        "L1B_DIRECTION_MISMATCH",
                        "L1b",
                        location,
                        "direction words disagree with the cited values",
                    )
                )
        elif len(remaining) == 1:
            violations.append(
                Violation(
                    "L1B_DIRECTION_MISMATCH",
                    "L1b",
                    location,
                    "direction words disagree with the cited values",
                )
            )
        else:
            pairs = [
                (binding.period, ref.value)
                for binding, ref in zip(known, remaining)
                if binding.period is not None
            ]
            ordered = sorted(pairs, key=lambda pair: _PERIOD_ORDER[pair[0]])
            diffs = [
                Decimal(str(later)) - Decimal(str(earlier))
                for (_, earlier), (_, later) in itertools.pairwise(ordered)
            ]
            agree = (
                all(diff > 0 for diff in diffs)
                if side == "up"
                else all(diff < 0 for diff in diffs)
            )
            if not agree:
                violations.append(
                    Violation(
                        "L1B_DIRECTION_MISMATCH",
                        "L1b",
                        location,
                        "direction words disagree with the cited values",
                    )
                )
    return violations


def _l1b_checks(briefing: Briefing, context: GateContext) -> list[Violation]:
    violations: list[Violation] = []
    for section_type, claim in _iter_claims(briefing):
        location = _claim_location(section_type, claim.id)
        known_ids = set(claim.fact_ids) | {ref.metric_id for ref in claim.metric_refs}
        if not claim.fact_ids and not claim.metric_refs:
            violations.append(
                Violation(
                    "L1B_CLAIM_WITHOUT_EVIDENCE",
                    "L1b",
                    location,
                    "claim has no fact or metric evidence",
                )
            )
        for fact_id in claim.fact_ids:
            fact = context.facts.get(fact_id)
            if fact is None or fact.subject_id != briefing.subject_id:
                violations.append(
                    Violation(
                        "L1B_UNKNOWN_FACT",
                        "L1b",
                        location,
                        "fact is unknown or belongs to another subject",
                    )
                )
        for token in extract_number_tokens(claim.text, known_ids):
            if not any(
                _ref_backs_token(ref.value, token.places, abs(token.value))
                for ref in claim.metric_refs
            ):
                violations.append(
                    Violation(
                        "L1B_NUMBER_WITHOUT_METRIC_REF",
                        "L1b",
                        location,
                        "number token has no backing metric ref",
                    )
                )
        violations.extend(_binding_violations(section_type, claim, context, location))
        if section_type == "since_last":
            continue
        for ref in claim.metric_refs:
            if ref.metric_id not in context.metrics.values:
                violations.append(
                    Violation(
                        "L1B_UNKNOWN_METRIC",
                        "L1b",
                        location,
                        "metric is absent from the snapshot",
                    )
                )
            elif Decimal(str(ref.value)) != Decimal(
                str(context.metrics.values[ref.metric_id])
            ):
                violations.append(
                    Violation(
                        "L1B_METRIC_VALUE_MISMATCH",
                        "L1b",
                        location,
                        "metric value differs from the snapshot",
                    )
                )
    parent_id = briefing.parent_briefing_id
    if parent_id is not None:
        if (
            context.parent_briefing is None
            or context.parent_metrics is None
            or context.parent_briefing.id != parent_id
            or context.parent_briefing.profile_id != briefing.profile_id
            or context.parent_briefing.subject_id != briefing.subject_id
            or not (context.parent_briefing.slot < briefing.slot)
        ):
            violations.append(
                Violation(
                    "L1B_PARENT_MISMATCH",
                    "L1b",
                    "parent_briefing_id",
                    "parent briefing does not match the context",
                )
            )
        since_last = next(
            (section for section in briefing.sections if section.type == "since_last"),
            None,
        )
        if since_last is None:
            violations.append(
                Violation(
                    "L1B_MISSING_SINCE_LAST",
                    "L1b",
                    "sections",
                    "parent briefing requires a since_last section",
                )
            )
        else:
            parent_values = (
                context.parent_metrics.values
                if context.parent_metrics is not None
                else None
            )
            for claim in since_last.claims:
                location = _claim_location(since_last.type, claim.id)
                for ref in claim.metric_refs:
                    if (
                        ref.metric_id not in context.metrics.values
                        or parent_values is None
                        or ref.metric_id not in parent_values
                    ) or Decimal(str(ref.value)) != (
                        Decimal(str(context.metrics.values[ref.metric_id]))
                        - Decimal(str(parent_values[ref.metric_id]))
                    ):
                        violations.append(
                            Violation(
                                "L1B_DELTA_MISMATCH",
                                "L1b",
                                location,
                                "metric value differs from current-minus-parent",
                            )
                        )
    else:
        if context.parent_briefing is not None or context.parent_metrics is not None:
            violations.append(
                Violation(
                    "L1B_PARENT_MISMATCH",
                    "L1b",
                    "parent_briefing_id",
                    "parent briefing does not match the context",
                )
            )
        for section in briefing.sections:
            if section.type != "since_last":
                continue
            violations.append(
                Violation(
                    "L1B_SINCE_LAST_WITHOUT_PARENT",
                    "L1b",
                    _section_location(section.type),
                    "since_last section has no parent briefing",
                )
            )
            for claim in section.claims:
                location = _claim_location(section.type, claim.id)
                for ref in claim.metric_refs:
                    violations.append(
                        Violation(
                            "L1B_DELTA_MISMATCH",
                            "L1b",
                            location,
                            "metric value differs from current-minus-parent",
                        )
                    )
    return violations


def evaluate_briefing(
    raw: Briefing | Mapping[str, Any], context: GateContext
) -> GateResult:
    """Gate one briefing against reference data (pure, deterministic)."""
    pre_scan: list[Violation] = []
    unknown_indexes: set[int] = set()
    raw_obj = cast("object", raw)
    if isinstance(raw_obj, Briefing):
        briefing = raw_obj
    elif not isinstance(raw_obj, Mapping):
        return _finish(
            [
                Violation(
                    "L0_SCHEMA_INVALID",
                    "L0",
                    "briefing",
                    "briefing does not match the schema",
                )
            ]
        )
    else:
        raw_mapping = cast("Mapping[str, Any]", raw_obj)
        sections_obj: object = raw_mapping.get("sections")
        if isinstance(sections_obj, list):
            sections = cast("list[Any]", sections_obj)
            for index in range(len(sections)):
                section_obj: object = sections[index]
                if isinstance(section_obj, dict):
                    raw_section = cast("dict[str, Any]", section_obj)
                    section_type: object = raw_section.get("type")
                else:
                    section_type = None
                if (
                    not isinstance(section_type, str)
                    or section_type not in KNOWN_SECTION_TYPES
                ):
                    unknown_indexes.add(index)
                    pre_scan.append(
                        Violation(
                            "L0_UNKNOWN_SECTION",
                            "L0",
                            f"sections[{index}]",
                            "unknown section type",
                        )
                    )
        try:
            briefing = Briefing.model_validate(raw)
        except ValidationError as exc:
            schema_errors: list[Violation] = []
            for error in exc.errors():
                loc = error.get("loc", ())
                if (
                    len(loc) == 3
                    and loc[0] == "sections"
                    and isinstance(loc[1], int)
                    and loc[1] in unknown_indexes
                    and loc[2] == "type"
                ):
                    continue
                location = ".".join(str(part) for part in loc)
                schema_errors.append(
                    Violation(
                        "L0_SCHEMA_INVALID",
                        "L0",
                        location,
                        "briefing does not match the schema",
                    )
                )
            return _finish(pre_scan + schema_errors)
    violations = list(pre_scan)
    violations.extend(_l0_counts(briefing, context))
    violations.extend(_l1_text_checks(briefing, context))
    violations.extend(_l1_metric_ref_raw_check(briefing, context))
    violations.extend(_l1_commitment_checks(briefing, context))
    violations.extend(_l1_slot_and_interval_checks(briefing, context))
    violations.extend(_l1b_checks(briefing, context))
    return _finish(violations)


def _finish(violations: list[Violation]) -> GateResult:
    seen: set[tuple[str, str]] = set()
    unique: list[Violation] = []
    for violation in sorted(violations, key=lambda v: (v.layer, v.code, v.location)):
        key = (violation.code, violation.location)
        if key not in seen:
            seen.add(key)
            unique.append(violation)
    return GateResult(violations=tuple(unique))


def collapse_text(text: str) -> str:
    """Ticket 17a: public wrapper over ``_collapse``; nothing else changed."""
    return _collapse(text)


def contains_token(text: str, literal: str) -> bool:
    """Ticket 17a: public wrapper over ``_contains_token``; nothing else changed."""
    return _contains_token(text, literal)


def ref_backs_token(value: float, places: int, token_abs: Decimal) -> bool:
    """Ticket 17a: public wrapper over ``_ref_backs_token``.

    Fail closed: an ``InvalidOperation`` from rounding means no backing,
    never a traceback.
    """
    import decimal

    try:
        return _ref_backs_token(value, places, token_abs)
    except decimal.InvalidOperation:
        return False


def word_list_hit(text: str, words: tuple[str, ...] | list[str]) -> bool:
    """Ticket 17a: whole-token match over caller words, like the advice arm."""
    normalized = _collapse(text).replace("\u2019", "'").replace("\u2018", "'")
    return any(
        bool(word)
        and _contains_token(
            normalized, _collapse(word).replace("\u2019", "'").replace("\u2018", "'")
        )
        for word in words
    )


def direction_sides(
    text: str, *, exclude_words: tuple[str, ...] | list[str]
) -> frozenset[str]:
    """Ticket 17a: direction sides named in ``text``, minus label tokens."""
    excluded: set[str] = set()
    for word in exclude_words:
        excluded.update(_DIRECTION_TOKEN_RE.findall(_collapse(word)))
    tokens = set(_DIRECTION_TOKEN_RE.findall(_collapse(text))) - excluded
    sides: set[str] = set()
    if tokens & _UP_WORDS:
        sides.add("up")
    if tokens & _DOWN_WORDS:
        sides.add("down")
    return frozenset(sides)


ADVICE_WORDS: tuple[str, ...] = tuple(sorted(_ADVICE_SINGLES)) + tuple(_ADVICE_PHRASES)
"""Ticket 17a: the gate's pinned advice list, for callers replicating it."""

framework/briefing/labels.py:
"""Ticket 10: metric label bindings (which prose names which metric).

One pure function over the metric id: no I/O, no env, no clock.
"""

from __future__ import annotations

from dataclasses import dataclass

_PUSH_LABELS = frozenset({"push", "pushes", "pushed", "pushing"})
_PR_LABELS = frozenset({"pr", "prs", "pull request", "pull requests"})
_FEED_LABELS = frozenset({"feed", "feeds"})

_PERIODS = ("earlier", "prior", "last")
_FEED_PREFIX = "feed.item.count"


@dataclass(frozen=True)
class MetricBinding:
    """Accepted prose for one metric id."""

    labels: frozenset[str]
    period: str | None
    family: str
    requires_cancel: bool


def _screen_labels(category: str) -> frozenset[str] | None:
    if not category or not category.strip():
        return None
    last = category.rsplit("/", 1)[-1]
    if not last or not last.strip():
        return None
    return frozenset({category, last})


def _tag_labels(tag: str) -> frozenset[str] | None:
    if not tag or not tag.strip():
        return None
    if tag.startswith("iki-"):
        word = tag[len("iki-") :]
        if not word or not word.strip():
            return None
        return frozenset({tag, word})
    return frozenset({tag})


def metric_label_binding(metric_id: str) -> MetricBinding | None:
    """Return the prose binding for ``metric_id``, or ``None`` (unknown)."""
    period: str | None = None
    remainder = metric_id
    for name in _PERIODS:
        prefix = f"period.{name}."
        if metric_id.startswith(prefix):
            period, remainder = name, metric_id[len(prefix) :]
            break
    else:
        if metric_id.startswith("period."):
            return None

    if remainder.startswith("screen_hours."):
        labels = _screen_labels(remainder[len("screen_hours.") :])
        if labels is None:
            return None
        return MetricBinding(labels, period, remainder, False)
    if remainder.startswith("tag_hours."):
        labels = _tag_labels(remainder[len("tag_hours.") :])
        if labels is None:
            return None
        return MetricBinding(labels, period, remainder, False)
    if period is None:
        if remainder == "github.push.count":
            return MetricBinding(_PUSH_LABELS, period, remainder, False)
        if remainder == "github.pr.count":
            return MetricBinding(_PR_LABELS, period, remainder, False)
        if remainder == "calendar.busy_hours":
            return MetricBinding(frozenset({"busy"}), period, remainder, False)
        if remainder == _FEED_PREFIX:
            return MetricBinding(_FEED_LABELS, period, remainder, False)
        if remainder.startswith(_FEED_PREFIX + "."):
            if not remainder[len(_FEED_PREFIX) + 1 :].strip():
                return None
            return MetricBinding(_FEED_LABELS, period, remainder, False)
        return None
    if remainder == "pushes":
        return MetricBinding(_PUSH_LABELS, period, remainder, False)
    if remainder == "prs":
        return MetricBinding(_PR_LABELS, period, remainder, False)
    if remainder.startswith("cancelled."):
        labels = _tag_labels(remainder[len("cancelled.") :])
        if labels is None:
            return None
        return MetricBinding(labels, period, remainder, True)
    return None

framework/schemas/manifest.py:
"""Manifest, BlockConfig base and Decision schemas (SPEC section 3)."""

from typing import Annotated, Any, Literal

from pydantic import Field, model_validator

from framework.schemas.base import Dimension, SchemaModel
from framework.schemas.events import NonEmptyStr


class BlockConfig(SchemaModel):
    type: NonEmptyStr
    dimension: Dimension
    config: dict[str, Any] = Field(default_factory=dict)
    rationale: str = ""


class ChangelogEntry(SchemaModel):
    from_version: str | None = Field(default=None, alias="from")
    change: str
    why: str
    evidence: Annotated[list[NonEmptyStr], Field(min_length=1)]


class Manifest(SchemaModel):
    version: NonEmptyStr
    parent: str | None
    layout: list[str]
    blocks: dict[str, BlockConfig]
    changelog: list[ChangelogEntry]


class ManifestDiff(SchemaModel):
    base_version: NonEmptyStr
    candidate: Manifest


DecisionKind = Literal["noop", "evolve", "recalibrate", "refine_objective"]


class Decision(SchemaModel):
    kind: DecisionKind
    rationale: str
    evidence: list[NonEmptyStr]
    manifest_diff: ManifestDiff | None = None

    @model_validator(mode="after")
    def _kind_rules(self) -> "Decision":
        if self.kind == "evolve":
            if self.manifest_diff is None:
                raise ValueError("evolve decisions require manifest_diff")
            if self.manifest_diff.candidate.parent != self.manifest_diff.base_version:
                raise ValueError(
                    "manifest_diff candidate parent must equal base_version"
                )
        elif self.manifest_diff is not None:
            raise ValueError("manifest_diff is only allowed for evolve decisions")
        if self.kind != "noop":
            if not self.rationale.strip():
                raise ValueError("non-noop decisions require a rationale")
            if not self.evidence:
                raise ValueError("non-noop decisions require evidence")
        return self

framework/verify/core.py:
"""Ticket 17a: public claim checker over plain JSON.

``verify_claims`` reconciles an agent's stated numbers and cited sources
against caller-supplied reference data. It shares its matching path with
the briefing gate (``text_check_codes``, ``extract_number_tokens`` and the
appended wrappers in ``framework.briefing.gate``) and adds nothing else.
No network, no model, no store, no profile: the caller brings the facts
and metrics from their own system of record.
"""

from __future__ import annotations

import itertools
import json
import math
import re
from collections.abc import Mapping
from dataclasses import dataclass
from decimal import Decimal
from typing import Annotated, Any

from pydantic import (
    AfterValidator,
    BaseModel,
    ConfigDict,
    Field,
    StrictFloat,
    StrictInt,
    ValidationError,
    field_validator,
    model_validator,
)

from framework.briefing.gate import (
    collapse_text,
    contains_token,
    direction_sides,
    ref_backs_token,
    text_check_codes,
    word_list_hit,
)
from framework.briefing.numbers import extract_number_tokens

LIMITS_NOTE = (
    "This check covers parseable numbers, cited sources, labels and direction. "
    "It does not check that a sentence is true. "
    "Without labels it cannot tell which metric a number belongs to, "
    "and a cited fact is only checked to exist."
)

MAX_CLAIM_TEXT_CHARS = 2_000
MAX_TOTAL_CLAIM_TEXT_CHARS = 100_000
MAX_INPUT_BYTES = 10_000_000
MAX_CLAIMS = 5_000
MAX_REFS_PER_CLAIM = 100
MAX_TERMS = 1_000
MAX_LABEL_WORDS = 10
MAX_SERIES_IDS = 366
MAX_JSON_DEPTH = 64
MAX_WORD_CHARS = 100
MAX_CLAIM_ID_CHARS = 200

_FIELD_NAMES = frozenset(
    {
        "claims",
        "id",
        "text",
        "fact_ids",
        "metric_refs",
        "metric_id",
        "value",
        "facts",
        "metrics",
        "labels",
        "order",
        "deny_terms",
        "advice_words",
    }
)


class VerifyInputError(ValueError):
    """Bad checker input; safe to print and to send back to a model."""


def _non_blank(value: str) -> str:
    if not value.strip():
        raise ValueError("string must not be blank")
    return value


NonBlankStr = Annotated[str, AfterValidator(_non_blank)]
StrictNumber = Annotated[StrictInt | StrictFloat, Field(union_mode="left_to_right")]


def _finite_number(value: StrictNumber) -> StrictNumber:
    if isinstance(value, bool):
        raise TypeError("metric value must be a number")
    if isinstance(value, int) and value.bit_length() > 14_000:
        raise ValueError("metric value is too large")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("metric value must be finite")
    return value


class MetricRefInput(BaseModel):
    """One cited metric value on a claim."""

    model_config = ConfigDict(extra="forbid")

    metric_id: NonBlankStr
    value: StrictNumber

    @field_validator("value")
    @classmethod
    def _finite_value(cls, value: float) -> int | float:
        return _finite_number(value)


class ClaimInput(BaseModel):
    """One statement plus its evidence."""

    model_config = ConfigDict(extra="forbid")

    id: NonBlankStr
    text: NonBlankStr
    fact_ids: Annotated[list[NonBlankStr], Field(default_factory=list, fail_fast=True)]
    metric_refs: Annotated[
        list[MetricRefInput], Field(default_factory=list, fail_fast=True)
    ]

    @field_validator("id")
    @classmethod
    def _id_capped(cls, value: str) -> str:
        if len(value) > MAX_CLAIM_ID_CHARS:
            raise ValueError(
                f"claim id exceeds MAX_CLAIM_ID_CHARS ({MAX_CLAIM_ID_CHARS})"
            )
        return value

    @field_validator("text")
    @classmethod
    def _text_capped(cls, value: str) -> str:
        if len(value) > MAX_CLAIM_TEXT_CHARS:
            raise ValueError(
                f"claim text exceeds MAX_CLAIM_TEXT_CHARS ({MAX_CLAIM_TEXT_CHARS})"
            )
        return value

    @field_validator("metric_refs")
    @classmethod
    def _refs_capped(cls, value: list[MetricRefInput]) -> list[MetricRefInput]:
        if len(value) > MAX_REFS_PER_CLAIM:
            raise ValueError(
                f"claim refs exceed MAX_REFS_PER_CLAIM ({MAX_REFS_PER_CLAIM})"
            )
        return value


class VerifyInput(BaseModel):
    """The whole public input: agent output plus reference data."""

    model_config = ConfigDict(extra="forbid")

    claims: Annotated[list[ClaimInput], Field(fail_fast=True)]
    facts: dict[str, str]
    metrics: dict[str, StrictNumber]
    labels: dict[str, Annotated[list[str], Field(fail_fast=True)]] | None = None
    order: Annotated[
        list[Annotated[list[NonBlankStr], Field(fail_fast=True)]] | None,
        Field(default=None, fail_fast=True),
    ] = None
    deny_terms: Annotated[
        list[NonBlankStr] | None, Field(default=None, fail_fast=True)
    ] = None
    advice_words: Annotated[
        list[NonBlankStr] | None, Field(default=None, fail_fast=True)
    ] = None

    @field_validator("facts")
    @classmethod
    def _facts_non_blank(cls, value: dict[str, str]) -> dict[str, str]:
        for key, item in value.items():
            if not key.strip():
                raise ValueError("fact id must not be blank")
            if not item.strip():
                raise ValueError("fact value must not be blank")
        return value

    @field_validator("metrics")
    @classmethod
    def _metrics_valid(cls, value: dict[str, int | float]) -> dict[str, int | float]:
        for key, item in value.items():
            if not key.strip():
                raise ValueError("metric id must not be blank")
            _finite_number(item)
        return value

    @field_validator("labels")
    @classmethod
    def _labels_valid(
        cls, value: dict[str, list[str]] | None
    ) -> dict[str, list[str]] | None:
        if value is None:
            return value
        for key, words in value.items():
            if not key.strip():
                raise ValueError("label id must not be blank")
            if not words:
                raise ValueError("label word list must not be empty")
            if len(words) > MAX_LABEL_WORDS:
                raise ValueError(
                    f"label word list exceeds MAX_LABEL_WORDS ({MAX_LABEL_WORDS})"
                )
            for word in words:
                if not word.strip():
                    raise ValueError("label word must not be blank")
                if len(word) > MAX_WORD_CHARS:
                    raise ValueError(
                        f"label word exceeds MAX_WORD_CHARS ({MAX_WORD_CHARS})"
                    )
        return value

    @field_validator("deny_terms", "advice_words")
    @classmethod
    def _terms_capped(cls, value: list[str] | None) -> list[str] | None:
        if value is not None and len(value) > MAX_TERMS:
            raise ValueError(f"term list exceeds MAX_TERMS ({MAX_TERMS})")
        if value is not None:
            for term in value:
                if len(term) > MAX_WORD_CHARS:
                    raise ValueError(f"term exceeds MAX_WORD_CHARS ({MAX_WORD_CHARS})")
        return value

    @model_validator(mode="after")
    def _claims_capped(self) -> VerifyInput:
        if not self.claims:
            raise ValueError("claims must not be empty")
        if len(self.claims) > MAX_CLAIMS:
            raise ValueError(f"claims exceed MAX_CLAIMS ({MAX_CLAIMS})")
        seen: set[str] = set()
        for claim in self.claims:
            if claim.id in seen:
                raise ValueError("claim id appears more than once")
            seen.add(claim.id)
        total = sum(len(claim.text) for claim in self.claims)
        if total > MAX_TOTAL_CLAIM_TEXT_CHARS:
            raise ValueError(
                "total claim text exceeds "
                f"MAX_TOTAL_CLAIM_TEXT_CHARS ({MAX_TOTAL_CLAIM_TEXT_CHARS})"
            )
        if self.order is not None:
            seen_order: set[str] = set()
            for series in self.order:
                if len(series) < 2:
                    raise ValueError("order series must hold at least 2 metric ids")
                if len(series) > MAX_SERIES_IDS:
                    raise ValueError(
                        f"order series exceeds MAX_SERIES_IDS ({MAX_SERIES_IDS})"
                    )
                for metric_id in series:
                    if metric_id in seen_order:
                        raise ValueError("order metric id appears more than once")
                    seen_order.add(metric_id)
        return self


@dataclass(frozen=True)
class Violation:
    """One finding; ``message`` never echoes matched content."""

    code: str
    claim_id: str
    message: str


@dataclass(frozen=True)
class Report:
    """Violations plus the pinned limits note."""

    violations: tuple[Violation, ...]
    limits: str

    @property
    def passed(self) -> bool:
        """Input passes iff it has no violations."""
        return self.violations == ()

    def feedback(self) -> str:
        """One ``CODE claim_id: message`` line per violation."""
        return "\n".join(f"{v.code} {v.claim_id}: {v.message}" for v in self.violations)


_TEXT_MESSAGES = {
    "L1_SECRET": "secret-like token",
    "L1_PII": "contact detail",
    "L1_PRIVATE_TERM": "private term",
    "L1_ADVICE": "advice-like wording",
}


_TYPE_WORDS = {
    "missing": "missing",
    "extra_forbidden": "unknown key",
    "model_type": "must be an object",
    "model_attributes_type": "must be an object",
    "dict_type": "must be an object",
    "list_type": "must be a list",
    "string_type": "must be a string",
    "string_unicode": "must be valid text",
    "int_type": "must be a number",
    "float_type": "must be a number",
}

_VALUE_ERROR_PREFIX = "Value error, "


def _safe_message(exc: ValidationError) -> str:
    errors = exc.errors(include_input=False, include_url=False, include_context=False)
    lines: list[str] = []
    seen_lines: set[str] = set()
    for error in errors:
        error_type = str(error.get("type", "value_error"))
        parts = list(error.get("loc", ()))
        if error_type in ("int_type", "float_type") and parts:
            parts = parts[:-1]
        safe_loc = ".".join(
            str(part) if isinstance(part, int) or part in _FIELD_NAMES else "<key>"
            for part in parts
        )
        if error_type == "value_error":
            detail = str(error.get("msg", "")).removeprefix(_VALUE_ERROR_PREFIX)
        else:
            detail = _TYPE_WORDS.get(error_type, error_type)
        line = f"{safe_loc}: {detail}" if safe_loc else detail
        if line not in seen_lines:
            seen_lines.add(line)
            lines.append(line)
    text = "; ".join(lines[:5]) if lines else "invalid input"
    rest = len(lines) - 5
    if rest > 0:
        text += f"; and {rest} more"
    return text


def _validate(parsed: Any) -> VerifyInput:
    if isinstance(parsed, VerifyInput):
        parsed = parsed.model_dump()
    if not isinstance(parsed, dict):
        raise VerifyInputError("input must be a JSON object")
    try:
        return VerifyInput.model_validate(parsed)
    except ValidationError as exc:
        raise VerifyInputError(_safe_message(exc)) from None


_JSON_TOKEN_RE = re.compile(r'"(?:[^"\\]++|\\.?+)*+(?:"|\Z)|[\[\]{}]', re.DOTALL)


def _check_depth(text: str) -> None:
    """Reject deep nesting before ``json.loads`` sees it.

    Only strings and brackets are walked, so brackets inside a string
    never count and a long string costs one match. Past the cap the
    browser build dies in the JS stack before Python's recursion check
    fires, so fail here with a named limit instead. ``\\Z`` lets an
    unclosed string run to the end of the text, so every match consumes
    and the search never restarts at each escaped quote.
    """
    depth = 0
    for match in _JSON_TOKEN_RE.finditer(text):
        token = match.group(0)
        if token == "[" or token == "{":
            depth += 1
            if depth > MAX_JSON_DEPTH:
                raise VerifyInputError(
                    f"input nests deeper than MAX_JSON_DEPTH ({MAX_JSON_DEPTH})"
                )
        elif token == "]" or token == "}":
            depth = max(0, depth - 1)


def load_input(raw: str | bytes) -> VerifyInput:
    """Parse one JSON input; every failure is a ``VerifyInputError``."""
    # Runtime callers bypass the annotation, so this guard stays.
    if not isinstance(raw, (str, bytes)):  # pyright: ignore[reportUnnecessaryIsInstance]
        raise VerifyInputError("input must be text or bytes")
    try:
        data = raw.encode("utf-8") if isinstance(raw, str) else raw
    except (ValueError, RecursionError) as exc:
        raise VerifyInputError("input is not valid UTF-8") from exc
    if len(data) > MAX_INPUT_BYTES:
        raise VerifyInputError(f"input exceeds MAX_INPUT_BYTES ({MAX_INPUT_BYTES})")
    try:
        text = data.decode("utf-8-sig")
    except (ValueError, RecursionError) as exc:
        raise VerifyInputError("input is not valid UTF-8") from exc
    _check_depth(text)

    def _no_dup(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        obj: dict[str, Any] = {}
        for key, item in pairs:
            if key in obj:
                raise ValueError("duplicate key")
            obj[key] = item
        return obj

    def _no_const(name: str) -> Any:
        raise ValueError(f"non-finite constant: {name}")

    try:
        parsed = json.loads(text, parse_constant=_no_const, object_pairs_hook=_no_dup)
    except (ValueError, RecursionError) as exc:
        raise VerifyInputError("input is not valid JSON") from exc
    return _validate(parsed)


@dataclass(frozen=True)
class _ClaimContext:
    """Lookups built once per run, so a claim walks only its own series."""

    facts: Mapping[str, str]
    metrics: Mapping[str, int | float]
    label_words: dict[str, tuple[str, ...]]
    series_index: dict[str, tuple[int, int]]
    series_words: dict[int, tuple[str, ...]]
    deny_terms: tuple[str, ...]
    advice_words: tuple[str, ...] | None


def _check_claim(
    claim: ClaimInput,
    ctx: _ClaimContext,
    add: Any,
) -> None:
    facts = ctx.facts
    metrics = ctx.metrics
    label_words = ctx.label_words
    series_index = ctx.series_index
    series_words = ctx.series_words
    deny_terms = ctx.deny_terms
    advice_words = ctx.advice_words
    if not claim.fact_ids and not claim.metric_refs:
        add(
            "L1B_CLAIM_WITHOUT_EVIDENCE",
            claim.id,
            "claim has no fact or metric evidence",
        )
    for fact_id in claim.fact_ids:
        if fact_id not in facts:
            add("L1B_UNKNOWN_FACT", claim.id, "cited fact is unknown")
    for ref in claim.metric_refs:
        if ref.metric_id not in metrics:
            add(
                "L1B_UNKNOWN_METRIC",
                claim.id,
                "metric is absent from the snapshot",
            )
        elif Decimal(str(ref.value)) != Decimal(str(metrics[ref.metric_id])):
            add(
                "L1B_METRIC_VALUE_MISMATCH",
                claim.id,
                "metric value differs from the snapshot",
            )
    known_ids = set(claim.fact_ids) | {ref.metric_id for ref in claim.metric_refs}
    for token in extract_number_tokens(claim.text, known_ids):
        if not any(
            ref_backs_token(ref.value, token.places, abs(token.value))
            for ref in claim.metric_refs
        ):
            add(
                "L1B_NUMBER_WITHOUT_METRIC_REF",
                claim.id,
                "number token has no backing metric ref",
            )
    bound = [
        ref
        for ref in claim.metric_refs
        if ref.metric_id in label_words or ref.metric_id in series_index
    ]
    if bound:
        ids = [ref.metric_id for ref in bound]
        inside = (
            len(set(ids)) == len(ids)
            and all(metric_id in series_index for metric_id in ids)
            and len({series_index[metric_id][0] for metric_id in ids}) == 1
        )
        if len(bound) >= 2 and not inside:
            add(
                "L1B_TOO_MANY_METRICS",
                claim.id,
                "claim cites several metrics outside one declared series; "
                "split the claim or list them in order",
            )
        else:
            collapsed = collapse_text(claim.text)
            bound_words = {
                word for metric_id in ids for word in label_words.get(metric_id, ())
            }
            missing = any(not contains_token(collapsed, word) for word in bound_words)
            if missing:
                add(
                    "L1B_METRIC_LABEL_MISSING",
                    claim.id,
                    "claim does not name the cited metric",
                )
            else:
                home: int = series_index[ids[0]][0] if ids[0] in series_index else -1
                named_sibling = False
                # A cited member's words are all in bound_words, so a word
                # outside bound_words can only belong to an uncited member.
                for word in series_words.get(home, ()):
                    if (
                        word not in bound_words
                        and word in collapsed
                        and contains_token(collapsed, word)
                    ):
                        named_sibling = True
                        break
                if named_sibling:
                    add(
                        "L1B_METRIC_LABEL_MISSING",
                        claim.id,
                        "claim names another metric in its series without citing it",
                    )
            exclude_words = [
                word for ref in bound for word in label_words.get(ref.metric_id, ())
            ]
            sides = direction_sides(claim.text, exclude_words=exclude_words)
            if len(sides) > 1:
                add(
                    "L1B_DIRECTION_MISMATCH",
                    claim.id,
                    "direction words disagree with the cited values",
                )
            elif sides:
                side = next(iter(sides))
                if len(bound) == 1:
                    add(
                        "L1B_DIRECTION_MISMATCH",
                        claim.id,
                        "direction words disagree with the cited values",
                    )
                else:
                    ordered = sorted(
                        bound, key=lambda ref: series_index[ref.metric_id][1]
                    )
                    diffs = [
                        Decimal(str(later.value)) - Decimal(str(earlier.value))
                        for earlier, later in itertools.pairwise(ordered)
                    ]
                    agree = (
                        all(diff > 0 for diff in diffs)
                        if side == "up"
                        else all(diff < 0 for diff in diffs)
                    )
                    if not agree:
                        add(
                            "L1B_DIRECTION_MISMATCH",
                            claim.id,
                            "direction words disagree with the cited values",
                        )
    for code in text_check_codes(claim.text, private_terms=deny_terms):
        if code == "L1_ADVICE":
            continue
        add(code, claim.id, _TEXT_MESSAGES.get(code, "text check failed"))
    if advice_words and word_list_hit(claim.text, advice_words):
        add("L1_ADVICE", claim.id, _TEXT_MESSAGES["L1_ADVICE"])


def verify_claims(data: VerifyInput | dict[str, Any] | str | bytes) -> Report:
    """Check agent output against reference data; bad input raises."""
    # Runtime callers bypass the annotation, so this guard stays.
    if not isinstance(data, (VerifyInput, dict, str, bytes)):  # pyright: ignore[reportUnnecessaryIsInstance]
        raise VerifyInputError("input must be a JSON object")
    if isinstance(data, (str, bytes)):
        validated = load_input(data)
    else:
        validated = _validate(data)
    violations: list[Violation] = []
    seen: set[tuple[str, str]] = set()

    def _add(code: str, claim_id: str, message: str) -> None:
        if (code, claim_id) not in seen:
            seen.add((code, claim_id))
            violations.append(Violation(code=code, claim_id=claim_id, message=message))

    label_words = {
        metric_id: tuple(collapse_text(word) for word in words)
        for metric_id, words in (validated.labels or {}).items()
    }
    series_index: dict[str, tuple[int, int]] = {}
    for series_no, series in enumerate(validated.order or []):
        for position, metric_id in enumerate(series):
            series_index[metric_id] = (series_no, position)
    grouped: dict[int, list[str]] = {}
    for series_no, series in enumerate(validated.order or []):
        for metric_id in series:
            for word in label_words.get(metric_id, ()):
                grouped.setdefault(series_no, []).append(word)
    ctx = _ClaimContext(
        facts=validated.facts,
        metrics=validated.metrics,
        label_words=label_words,
        series_index=series_index,
        series_words={
            key: tuple(dict.fromkeys(words)) for key, words in grouped.items()
        },
        deny_terms=tuple(
            dict.fromkeys(collapse_text(term) for term in validated.deny_terms or ())
        ),
        advice_words=tuple(
            dict.fromkeys(collapse_text(word) for word in validated.advice_words or ())
        )
        if validated.advice_words
        else None,
    )
    for claim in validated.claims:
        _check_claim(claim, ctx, _add)
    return Report(violations=tuple(violations), limits=LIMITS_NOTE)


def _safe_claim_id(claim_id: str) -> str:
    if claim_id.isprintable():
        return claim_id
    return claim_id.encode("unicode-escape").decode("ascii")


def format_report(report: Report) -> str:
    """Human report: PASS/FAIL, the limits note, then one line per finding."""
    lines = ["PASS" if report.passed else "FAIL", report.limits]
    lines.extend(
        f"{v.code} {_safe_claim_id(v.claim_id)}: {v.message}" for v in report.violations
    )
    return "\n".join(lines)


def page_render(raw: str) -> str:
    """Run the checker for the browser page; never raises, never echoes."""
    try:
        report = verify_claims(raw)
    except VerifyInputError as exc:
        return json.dumps({"exit_code": 2, "text": str(exc)})
    except Exception:  # noqa: BLE001 - the page shows a fixed message instead
        return json.dumps({"exit_code": 2, "text": "could not check that input"})
    return json.dumps(
        {
            "exit_code": 0 if report.passed else 1,
            "text": format_report(report),
        }
    )

